from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        if all(x == 0 for x in nums):
            return 0

        limit = max(nums)
        mask = (1 << (limit + 1)) - 1
        achievable = [1] * n

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                achievable[i] = (achievable[i] | (achievable[i] << val)) & mask

            if all((achievable[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1
